        private async Task OpenAdmin(SuperAdminDomain role)
        {
            try
            {
                IsLoading = true;
                string ApiUri1 = "SuperAdminModule/GetAdd_Module";
                moduleList = await httpService.Get<List<SuperAdminModule>>(ApiUri1) ?? new();
                moduleQuery = moduleList.AsQueryable();
                foreach (var module in moduleList)
                {
                    string ApiUri2 = $"SuperAdminModule/GetByModule/{module.ModuleId}";
                    module.Features = await httpService.Get<List<SuperAdminFeatures>>(ApiUri2) ?? new();
                    foreach (var feature in module.Features)
                    {
                        string ApiUri3 = $"SuperAdminModule/GetActivity/{feature.FeatureId}";
                        feature.Activites = await httpService.Get<List<SuperAdminActivity>>(ApiUri3) ?? new();
                    }
                }
                IsLoading = false;
                ResetAdminState();
                ExpandAll();
                SelectedRoleId = role.RoleId;
                SelectedRoleName = role.RoleName;

                if (RoleSavedMap.TryGetValue(role.RoleId, out var savedSet))
                {
                    foreach (var module in moduleList)
                    {
                        foreach (var feature in module.Features)
                        {
                            if (savedSet.Contains((module.ModuleId, feature.FeatureId)))
                            {
                                module.IsSaved = true;
                                feature.IsSaved = true;
                            }
                        }
                    }
                }

                await LoadRolePermissions(role.RoleId);
                ShowPopupAdmin = true;
            }
            catch (Exception)
            {

                throw;
            }
            
        }


        private void ApplySavedHighlight()
        {
            var role = superAdminlist.First(r => r.RoleId == SelectedRoleId);
            role.IsSaved = true;

            if (!RoleSavedMap.ContainsKey(SelectedRoleId))
                RoleSavedMap[SelectedRoleId] = new();

            foreach (var module in moduleList)
            {
                foreach (var feature in module.Features)
                {
                    if (feature.Activites.Any(a => a.IsSelected))
                    {
                        RoleSavedMap[SelectedRoleId]
                            .Add((module.ModuleId, feature.FeatureId));
                    }
                }
            }
        }

