        private string ToRoman(int number)
        {
            return number switch
            {
                1 => "i",
                2 => "ii",
                3 => "iii",
                4 => "iv",
                5 => "v",
                6 => "vi",
                7 => "vii",
                8 => "viii",
                9 => "ix",
                10 => "x",
                _ => number.ToString()
            };
          
        }

        private void ExpandAll()
        {
            foreach (var module in FilteredModules)
            {
                module.IsExpanded = true;

                if (module.Features != null)
                {
                    foreach (var feature in module.Features)
                    {
                        feature.IsExpanded = true;
                    }
                }
            }

        }
        private async Task LoadRolePermissions(int roleId)
        {
            var savedPermissions =
                await httpService.Get<List<ControlAccess>>($"SuperAdminModule/GetControlMappingByRole/{roleId}");

            if (savedPermissions == null || !savedPermissions.Any())
                return;

            ApplyPermissionsToUI(savedPermissions);
        }

        private void ApplyPermissionsToUI(List<ControlAccess> saved)
        {
            foreach (var module in moduleList)
            {
                foreach (var feature in module.Features)
                {
                    bool isAnyActivitySelected = false;
                    foreach (var act in feature.Activites)
                    {
                        var match = saved.FirstOrDefault(x =>
                            x.RoleId == SelectedRoleId &&
                            x.ModuleId == module.ModuleId &&
                            x.FeatureId == feature.FeatureId &&
                            x.ActivityId == act.ActivityId);

                        if (match != null)
                        {
                            isAnyActivitySelected = true;

                            act.IsSelected = true;
                            act.IsAdd = match.IsAdd;
                            act.IsModifiy = match.IsModifiy;
                            act.IsPrint = match.IsPrint;
                            act.IsExportToExcel = match.IsExportToExcel;
                            act.IsPII = match.IsPII;

                            act.Action1 = match.Action1;
                            act.Action2 = match.Action2;
                            act.Action3 = match.Action3;
                        }
                        else
                        {
                            act.IsSelected = false;
                        }
                    }
                    feature.IsSelected = isAnyActivitySelected;
                }
            }
        }

        private void ResetAdminState()
        {
            SelectedRoleId = 0;
            SelectedRoleName = string.Empty;

            SelectedModuleName = null;
            SelectedFeatureName = null;
            SelectedActivityName = null;

            superAdmin = new SuperAdminDomain();
            feat = new SuperAdminFeatures();

            foreach (var module in moduleList)
            {
                module.IsExpanded = false;

                foreach (var feature in module.Features)
                {
                    feature.IsExpanded = false;
                    feature.IsSelected = false;
                    module.IsSaved = false;
                    feature.IsSaved = false;

                    foreach (var act in feature.Activites)
                    {
                        act.IsSelected = false;
                        act.IsAdd = false;
                        act.IsModifiy = false;
                        act.IsPrint = false;
                        act.IsExportToExcel = false;
                        act.IsPII = false;
                        act.Action1 = false;
                        act.Action2 = false;
                        act.Action3 = false;
                    }
                }
            }
        }
        private async Task OnSuperAdminSave()
        {
            ShowPopupAdmin = false;

            var savedPermissions =await httpService.Get<List<ControlAccess>>( $"SuperAdminModule/GetControlMappingByRole/{SelectedRoleId}")
                ?? new List<ControlAccess>();

            var selectedActivities = moduleList .SelectMany(m => m.Features).SelectMany(f => f.Activites).Where(a => a.IsSelected).ToList();
            var controlAccessList = new List<ControlAccess>();

            foreach (var act in selectedActivities)
            {
                var feature = moduleList
                    .SelectMany(m => m.Features)
                    .First(f => f.FeatureId == act.FeatureId);

                var module = moduleList
                    .First(m => m.ModuleId == feature.ModuleId);

                controlAccessList.Add(new ControlAccess
                {
                    RoleId = SelectedRoleId,
                    ModuleId = module.ModuleId,
                    FeatureId = act.FeatureId,
                    ActivityId = act.ActivityId,
                    IsAdd = act.IsAdd,
                    IsModifiy = act.IsModifiy,
                    IsPrint = act.IsPrint,
                    IsExportToExcel = act.IsExportToExcel,
                    IsPII = act.IsPII,
                    Action1 = act.Action1,
                    Action2 = act.Action2,
                    Action3 = act.Action3,
                    CreatedBy = username
                });
            }

            var deleteList = savedPermissions.Where(sp => !selectedActivities.Any(a =>
                    a.ActivityId == sp.ActivityId &&
                    a.FeatureId == sp.FeatureId))
                .Select(sp => sp.AccessId)
                .ToList();

          
            if (controlAccessList.Any())
            {
               var apiResponse1 = await httpService.Post<ApiResponse<object>>( "SuperAdminModule/ControlMapping",controlAccessList);
                if (apiResponse1.Success)
                {
                    if (apiResponse1.ActionType == "Update")
                    {
                        await Alert.ShowSuccess("Access " + @Localizer["Updated"]);
                    }
                    else
                    {
                        await Alert.ShowSuccess("Access " + @Localizer["Saved"]);
                    }
                }
               

            }
            if (deleteList.Any())
            {
                await httpService.Post<ApiResponse<object>>( "SuperAdminModule/DeleteMapping",deleteList);
            }
            ApplySavedHighlight();
            ResetAdminState();
            StateHasChanged();

        }







       







